const icon=n=>`<svg class="icon icon-${n}" aria-hidden="true" viewBox="0 0 24 24">${SVG[n]||SVG.tag}</svg>`;
function icons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
const title=m=>m.title||m.name||'Sin título', kind=m=>m.media_type==='person'?'person':m.media_type==='tv'||m.first_air_date?'tv':'movie', keyOf=m=>`${kind(m)}:${m.id}`, year=m=>(m.release_date||m.first_air_date||'').slice(0,4)||'—', rating=m=>Number(m.vote_average||0).toFixed(1);
function readLocal(k, fallback){try{const v=JSON.parse(localStorage.getItem(k)||'null');return v??fallback}catch{return fallback}}
let list=readLocal('cs_list_v1',[]),follows=readLocal('cs_follow_v2',[]),history=readLocal('cs_history_v2',[]),recents=readLocal('cs_recent_v2',[]),profile=readLocal('cs_profile_v2',{name:'CarimarShow',avatar:''});
for(const pair of [[list,'list'],[follows,'follows'],[history,'history'],[recents,'recents']])if(!Array.isArray(pair[0])){if(pair[1]==='list')list=[];if(pair[1]==='follows')follows=[];if(pair[1]==='history')history=[];if(pair[1]==='recents')recents=[]}
let seed={catalog:[],details:{},people:{},images:{},responses:{},generatedAt:''},downloadMap=new Map(),visible=new Map(), routeRevision=0,searchRevision=0, searchType='multi', heroIndex=0,installPrompt=null,listTab='movie';
const view=$('#view');
const dbPromise=new Promise(resolve=>{if(!window.indexedDB)return resolve(null);const r=indexedDB.open('carimarshow-offline',2);r.onupgradeneeded=()=>{for(const s of ['api','images','downloads','pinnedImages'])if(!r.result.objectStoreNames.contains(s))r.result.createObjectStore(s)};r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result)};r.onblocked=()=>{toast('Cierra otras pestañas antiguas de CarimarShow y vuelve a abrir la app para actualizar el almacenamiento.');resolve(null)};r.onerror=()=>resolve(null)});
async function dbGet(store,key){const db=await dbPromise;if(!db)return null;return new Promise(resolve=>{try{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null)}catch{resolve(null)}})}
async function dbAll(store){const db=await dbPromise;if(!db)return [];return new Promise(resolve=>{try{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve([])}catch{resolve([])}})}
async function dbPut(store,key,value){const db=await dbPromise;if(!db)return false;return new Promise(resolve=>{try{const tx=db.transaction(store,'readwrite'),s=tx.objectStore(store);s.put(value,key);if(store==='api'||store==='images'){const r=s.getAllKeys();r.onsuccess=()=>{const max=store==='api'?250:100;for(const k of r.result.slice(0,Math.max(0,r.result.length-max)))s.delete(k)}}tx.oncomplete=()=>resolve(true);tx.onerror=tx.onabort=()=>resolve(false)}catch{resolve(false)}})}
async function dbClear(store){const db=await dbPromise;if(!db)return;return new Promise(resolve=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).clear();tx.oncomplete=tx.onerror=tx.onabort=resolve})}
async function dbDelete(store,key){const db=await dbPromise;if(!db)return;return new Promise(resolve=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=tx.onerror=tx.onabort=resolve})}
function localPut(k,value){try{localStorage.setItem(k,JSON.stringify(value));return true}catch{toast('No hay espacio disponible para guardar los cambios.');return false}}
function remember(items){for(const m of items||[])if(m.id)visible.set(keyOf(m),m)}
function getItem(k){return visible.get(k)||list.find(m=>keyOf(m)===k)||seed.catalog.find(m=>keyOf(m)===k)||history.find(m=>keyOf(m)===k)||downloadMap.get(k)?.item}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function initials(){if(profile.name==='CarimarShow')return 'CS';return (profile.name||'CarimarShow').split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase().slice(0,2)||'CS'}
function updateAvatar(){$('#headerAvatar').innerHTML=profile.avatar?`<img src="${esc(profile.avatar)}" alt="">`:esc(initials())}
function syncSaved(){document.querySelectorAll('[data-save]').forEach(b=>{const saved=list.some(m=>keyOf(m)===b.dataset.save);b.classList.toggle('saved',saved);b.innerHTML=icon(saved?'check':'plus');b.setAttribute('aria-label',saved?'Quitar de Mi lista':'Añadir a Mi lista');b.setAttribute('aria-pressed',String(saved))})}
function saveItem(m){if(!m)return;const exists=list.some(x=>keyOf(x)===keyOf(m)),next=exists?list.filter(x=>keyOf(x)!==keyOf(m)):[...list,{...m,media_type:kind(m)}];if(localPut('cs_list_v1',next)){list=next;syncSaved();toast(exists?'Eliminado de Mi lista':'Añadido a Mi lista')}}
function logVisit(m){const next=[{...m,viewedAt:new Date().toISOString()},...history.filter(x=>keyOf(x)!==keyOf(m))].slice(0,60);if(localPut('cs_history_v2',next))history=next}
function genres(){const all=new Map();for(const d of Object.values(seed.details))for(const g of d.genres||[])all.set(g.id,g);return [...all.values()]}
function seedFallback(path,params){
 const pin=downloadMap.get(path.replace('/',':'));if(pin)return pin.detail;
 if(seed.details[path])return seed.details[path];if(seed.people[path])return seed.people[path];
 if(/^genre\//.test(path))return seed.responses?.[path]||{genres:genres()};
 if(/\/videos$/.test(path)){const d=seed.details[path.replace('/videos','')];return d?.videos||{results:[]}}
 if(/^search\//.test(path)){const q=(params.query||'').toLocaleLowerCase('es'),type=path.split('/')[1];let found=seed.catalog.filter(m=>title(m).toLocaleLowerCase('es').includes(q));if(type==='movie'||type==='tv')found=found.filter(m=>kind(m)===type);const people=Object.values(seed.people).filter(p=>p.id&&p.name&&p.name.toLocaleLowerCase('es').includes(q)).map(p=>({...p,media_type:'person'}));return {results:type==='person'?people:type==='multi'?[...found,...people]:found,total_pages:1}}
 if(path==='person/popular')return {results:Object.values(seed.people).filter(p=>p.name&&p.id).map(p=>({...p,media_type:'person'})),total_pages:1};
 if(/^discover\//.test(path)){const type=path.split('/')[1],wanted=Number(params.with_genres);return {results:seed.catalog.filter(m=>kind(m)===type&&((m.genre_ids||[]).includes(wanted)||(seed.details[`${type}/${m.id}`]?.genres||[]).some(g=>g.id===wanted))),total_pages:1}}
 if(/\/(similar|recommendations)$/.test(path))return null;
 if(seed.responses?.[path]&&Number(params.page||1)===1)return seed.responses[path];
 if(/^(trending|movie\/|tv\/)/.test(path)&&!/^\w+\/\d+$/.test(path)){if(Number(params.page||1)>1)return {results:[],total_pages:1};const type=path.startsWith('movie/')?'movie':path.startsWith('tv/')?'tv':null;return {results:seed.catalog.filter(m=>!type||kind(m)===type),total_pages:1}}
 return null;
}
async function api(path,params={}){const query=new URLSearchParams({path,...params});query.sort();const key=query.toString();if(navigator.onLine){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),8000);try{const r=await fetch(`${window.CARIMAR_CONFIG.apiOrigin}/api/tmdb?${query}`,{signal:ctl.signal});if(!r.ok)throw Error();const d=await r.json();await dbPut('api',key,d);return d}catch{}finally{clearTimeout(timer)}}const cached=await dbGet('api',key);if(cached)return {...cached,_offline:true};const fallback=seedFallback(path,params);if(fallback)return {...fallback,_offline:true};throw Error('Esta información no está guardada. Conéctate para consultarla por primera vez.')}
const placeholder='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="300" height="450"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="#0e4057"/><stop offset="1" stop-color="#041726"/></linearGradient></defs><rect width="100%" height="100%" fill="url(#g)"/><text x="50%" y="50%" text-anchor="middle" fill="#4d829e" font-family="sans-serif" font-size="18">CarimarShow</text></svg>');
function image(p,size='w342',alt='',cls='poster'){if(!p||!/^\/[\w.-]+$/.test(p))return `<img class="${esc(cls)}" src="${placeholder}" alt="${esc(alt)}">`;const bundled=seed.images[size+p];return `<img class="${esc(cls)}" ${['hero-image','detail-image','actor-cover'].includes(cls)?'':'loading="lazy"'} src="${bundled?BASE+esc(bundled):placeholder}" data-image="${esc(size+p)}" ${bundled?'data-bundled="1"':''} alt="${esc(alt)}">`}
let observer;const urls=new Set();
async function hydrateImage(img){if(img.dataset.loaded)return;img.dataset.loaded='1';const k=img.dataset.image;let blob=await dbGet('pinnedImages',k)||await dbGet('images',k);if(!blob&&!img.dataset.bundled&&navigator.onLine){try{const r=await fetch('https://image.tmdb.org/t/p/'+k,{signal:AbortSignal.timeout(10000)});if(r.ok){const b=await r.blob();if(b.type.startsWith('image/')&&b.size<3000000){blob=b;await dbPut('images',k,b)}}}catch{}}if(blob instanceof Blob&&img.isConnected){const u=URL.createObjectURL(blob);urls.add(u);img.src=u}}
function hydrate(){if(observer)observer.disconnect();observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){hydrateImage(e.target);observer.unobserve(e.target)}}),{rootMargin:'120px'});document.querySelectorAll('[data-image]').forEach(i=>observer.observe(i));syncSaved();icons()}
function setView(html){for(const u of urls)URL.revokeObjectURL(u);urls.clear();view.innerHTML=html;hydrate()}
function offlineNote(d){return d?'<div class="notice">Sin conexión a TMDB. Mostramos datos guardados; las novedades se actualizarán cuando vuelva la conexión.</div>':''}
function empty(h,p,i='bookmark'){return `<div class="empty">${icon(i)}<h2>${esc(h)}</h2><p>${esc(p)}</p></div>`}
function head(h,back){return `<div class="page-head">${back?`<a class="back" href="${back}">${icon('back')}${esc(h)}</a>`:`<h1>${esc(h)}</h1>`}</div>`}
function section(h,to){return `<div class="section-head"><h2>${esc(h)}</h2>${to?`<a href="${to}">Ver todo ${icon('arrow')}</a>`:''}</div>`}
function card(m){if(kind(m)==='person')return `<a class="person-card" href="#person/${m.id}"><div class="poster-box">${image(m.profile_path,'w185',m.name)}</div><strong>${esc(m.name)}</strong><small>${esc(m.known_for_department||'Actuación')}</small></a>`;return `<article class="card"><div class="poster-box"><a class="poster-link" href="#detail/${kind(m)}/${m.id}" aria-label="Ver ${esc(title(m))}">${image(m.poster_path,'w342',title(m))}</a><button class="save" data-save="${keyOf(m)}" aria-label="Añadir a Mi lista">${icon('plus')}</button></div><h3><a href="#detail/${kind(m)}/${m.id}">${esc(title(m))}</a></h3><div class="subtitle"><span>${kind(m)==='tv'?'Serie':'Película'}</span><time>${year(m)}</time></div></article>`}
function cards(items,rail=false){remember(items);return `<div class="${rail?'rail':'grid'}">${items.map(card).join('')}</div>`}
function genreNames(m){const d=seed.details[`${kind(m)}/${m.id}`],gs=d?.genres||genres().filter(g=>(m.genre_ids||[]).includes(g.id));return gs.slice(0,3).map(g=>g.name).join(' · ')||`${kind(m)==='tv'?'Serie':'Película'} · ${year(m)}`}
function youtube(v){return v.site==='YouTube'&&/^[\w-]+$/.test(v.key)}
function trailerList(d){return (d.videos?.results||[]).filter(youtube).sort((a,b)=>(b.type==='Trailer')-(a.type==='Trailer'))}
function trailerLink(m,d){const v=trailerList(d||seed.details[`${kind(m)}/${m.id}`]||{})[0];return v?`<a class="primary" href="https://www.youtube.com/watch?v=${esc(v.key)}" target="_blank" rel="noopener">${icon('play')}Ver tráiler</a>`:`<a class="primary" href="#detail/${kind(m)}/${m.id}/trailers">${icon('play')}Ver tráiler</a>`}
function legal(){return '<p class="legal">Datos e imágenes de <a href="https://www.themoviedb.org" target="_blank" rel="noopener">TMDB</a>. Este producto utiliza la API de TMDB, pero no está respaldado ni certificado por TMDB.<br>Catálogo informativo: no reproduce ni descarga películas.</p>'}
async function home(rev){const [trending,fresh]=await Promise.all([api('trending/all/week'),api('movie/now_playing')]);if(rev!==routeRevision)return;const items=(trending.results||[]).filter(m=>kind(m)!=='person'),newItems=(fresh.results||[]).map(m=>({...m,media_type:'movie'}));const features=(seed.featured||[]).map(k=>seed.catalog.find(m=>keyOf(m)===k)).filter(Boolean);const heroes=(features.length?features:items.filter(m=>m.backdrop_path)).slice(0,3);remember([...items,...newItems,...heroes]);heroIndex=0;
 setView(`${offlineNote(trending._offline)}<div class="hero-slider"><div id="heroSlot"></div><div class="slider-dots">${heroes.map((_,i)=>`<button data-hero="${i}" class="${i===0?'active':''}" aria-label="Destacado ${i+1}"></button>`).join('')}</div></div><div class="home-sections"><section>${section('Tendencias','#browse/trending')}${cards(items.slice(0,12),true)}</section><section>${section('Nuevos lanzamientos','#browse/new')}${cards(newItems.slice(0,12),true)}</section><section>${section('Series para descubrir','#browse/tv')}${cards(items.filter(m=>kind(m)==='tv').slice(0,9),true)}</section><section>${section('Tu lista','#list')}${list.length?cards(list.slice(-9).reverse(),true):empty('Guarda tu próxima historia','Toca + en un título para encontrarlo aquí.')}</section></div>${legal()}`);
 function show(i){const m=heroes[i];if(!m)return;$('#heroSlot').innerHTML=`<section class="hero">${image(m.backdrop_path||m.poster_path,'w780','','hero-image')}<div class="hero-content"><span class="type-pill">${kind(m)==='tv'?'Serie':'Película'}</span><h1><a href="#detail/${kind(m)}/${m.id}">${esc(title(m))}</a></h1><p class="genres-line">${esc(genreNames(m))}</p><div class="hero-actions">${trailerLink(m)}<button class="circle-button" data-save="${keyOf(m)}" aria-label="Añadir a Mi lista">${icon('plus')}</button></div></div></section>`;document.querySelectorAll('[data-hero]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.hero)===i);b.setAttribute('aria-pressed',String(Number(b.dataset.hero)===i))});hydrate();heroIndex=i}
 show(0);document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>show(Number(b.dataset.hero)));
}
function trendRow(m){return `<a class="trend-item" href="#${kind(m)==='person'?'person/'+m.id:'detail/'+kind(m)+'/'+m.id}">${image(m.poster_path||m.profile_path,'w185',title(m))}<span class="title-copy"><strong>${esc(title(m))}</strong><small>${kind(m)==='tv'?'Serie':kind(m)==='person'?'Persona':'Película'}</small></span>${icon('arrow')}</a>`}
async function explore(rev,query=''){setView(`${head('Buscar')}<form id="searchForm" class="search-form"><label class="search-box">${icon('search')}<input type="search" id="query" aria-label="Buscar películas, series o personas" placeholder="Películas, series, actores…" maxlength="120" value="${esc(query)}" required></label><button type="button" class="plain-icon" id="filterButton" aria-label="Filtros de búsqueda">${icon('filter')}</button><button type="submit" class="plain-icon" aria-label="Buscar">${icon('arrow')}</button></form><p class="filter-count" id="searchFilterLabel"></p><div id="exploreDefault"><section><div class="section-head"><h2>Búsquedas recientes</h2><button class="text-button" id="clearRecent">Limpiar</button></div><div class="recent-chips" id="recentChips"></div></section>${section('Categorías')}<div class="search-category-grid"><a class="category-shortcut" href="#browse/movie">${icon('movie')}Películas</a><a class="category-shortcut" href="#browse/tv">${icon('tv')}Series</a><a class="category-shortcut" href="#browse/person">${icon('people')}Personas</a><a class="category-shortcut" href="#genres">${icon('tag')}Géneros</a></div>${section('Tendencias de hoy')}<div id="todayTrends" class="trend-list"><div class="loading-state">Consultando tendencias…</div></div></div><div id="searchResults" class="search-results" hidden></div>`);
 const labels={multi:'Todo',movie:'Películas',tv:'Series',person:'Personas / actores'};
 function recent(){if(!$('#recentChips'))return;$('#recentChips').innerHTML=recents.length?recents.map(q=>`<button data-recent="${esc(q)}">${esc(q)}</button>`).join(''):'<span class="muted tiny">Tus búsquedas aparecerán aquí.</span>';$('#searchFilterLabel').textContent='Buscar en: '+labels[searchType];}
 recent();$('#clearRecent').onclick=()=>{if(localPut('cs_recent_v2',[])){recents=[];recent()}};
 $('#filterButton').onclick=()=>{sheet(`<h2>Filtrar búsqueda</h2><label for="filterType">Buscar en</label><select id="filterType">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${searchType===k?'selected':''}>${v}</option>`).join('')}</select><button class="primary" id="applyFilter">Aplicar filtro</button>`);$('#applyFilter').onclick=()=>{searchType=$('#filterType').value;closeSheet();recent();if($('#query').value.trim())$('#searchForm').requestSubmit()}};
 $('#recentChips').onclick=e=>{const b=e.target.closest('[data-recent]');if(b){$('#query').value=b.dataset.recent;$('#searchForm').requestSubmit()}};
 $('#searchForm').onsubmit=async e=>{e.preventDefault();const q=$('#query').value.trim();if(!q)return;const seq=++searchRevision;const next=[q,...recents.filter(x=>x!==q)].slice(0,8);if(localPut('cs_recent_v2',next))recents=next;$('#exploreDefault').hidden=true;$('#searchResults').hidden=false;$('#searchResults').innerHTML='<div class="loading-state">Buscando en TMDB…</div>';try{const d=await api('search/'+searchType,{query:q});if(rev!==routeRevision||seq!==searchRevision)return;let result=d.results||[];if(searchType!=='multi')result=result.map(m=>({...m,media_type:searchType}));$('#searchResults').innerHTML=offlineNote(d._offline)+section(`Resultados para “${q}”`)+(result.length?cards(result):empty('No encontramos coincidencias','Prueba otro nombre. Sin conexión solo se busca en el catálogo incluido.','search'));hydrate()}catch(err){if(rev===routeRevision&&seq===searchRevision)$('#searchResults').innerHTML=empty('Necesitamos conexión',err.message,'offline')}};
 if(query)$('#searchForm').requestSubmit();
 try{const d=await api('trending/all/day');if(rev!==routeRevision)return;const items=(d.results||[]).filter(m=>kind(m)!=='person').slice(0,5);remember(items);if($('#todayTrends')){$('#todayTrends').innerHTML=offlineNote(d._offline)+items.map(trendRow).join('');hydrate()}}catch(err){if(rev===routeRevision&&$('#todayTrends'))$('#todayTrends').innerHTML=empty('No hay tendencias guardadas',err.message,'offline')}
}
async function browse(mode,rev,page=1,genreId=null,genreLabel=''){const maps={movie:['movie/popular','Películas'],tv:['tv/popular','Series'],person:['person/popular','Personas'],trending:['trending/all/week','Tendencias'],new:['movie/now_playing','Nuevos lanzamientos']};let [path,label]=maps[mode]||maps.movie;const params={page:String(page)};if(genreId){path='discover/'+mode;params.with_genres=String(genreId);label=genreLabel||'Explorar género'}const d=await api(path,params);if(rev!==routeRevision)return;const items=(d.results||[]).map(m=>({...m,media_type:m.media_type||(['movie','tv','person'].includes(mode)?mode:'movie')}));remember(items);
 if(page===1)setView(`${head(label,'#explore')}${offlineNote(d._offline)}<div id="browseCards">${items.length?cards(items):empty('No hay títulos guardados de esta categoría','Consulta con conexión para ampliar el catálogo.','movie')}</div><div class="more-wrap"><button class="secondary" id="loadMore">Cargar más</button></div>`);else{$('#browseCards').insertAdjacentHTML('beforeend',cards(items));hydrate()}
 const b=$('#loadMore');if(b){b.hidden=page>=Number(d.total_pages||1)||items.length===0;b.disabled=false;b.onclick=async()=>{b.disabled=true;try{await browse(mode,rev,page+1,genreId,genreLabel)}catch(e){toast(e.message);b.disabled=false}}}
}
async function genresPage(rev){const d=await api('genre/movie/list');if(rev!==routeRevision)return;const order=['Acción','Aventura','Comedia','Drama','Terror','Ciencia ficción','Romance','Fantasía'],all=[...(d.genres||[])].sort((a,b)=>{const ia=order.indexOf(a.name),ib=order.indexOf(b.name);return (ia<0?99:ia)-(ib<0?99:ib)});setView(`${head('Categorías','#explore')}${offlineNote(d._offline)}<div class="genre-tabs"><button class="active" data-genre-tab="all">Todos</button>${all.slice(0,6).map(g=>`<button data-genre-tab="${g.id}">${esc(g.name)}</button>`).join('')}</div><div class="genre-grid">${all.map(g=>{const m=seed.catalog.find(m=>(m.genre_ids||[]).includes(g.id))||seed.catalog.find(m=>(seed.details[`${kind(m)}/${m.id}`]?.genres||[]).some(x=>x.id===g.id));return `<a class="genre-tile" href="#genre/movie/${g.id}/${encodeURIComponent(g.name)}">${m?image(m.backdrop_path||m.poster_path,m.backdrop_path?'w780':'w342',g.name):''}<strong>${esc(g.name)}</strong></a>`}).join('')}</div>`);document.querySelectorAll('[data-genre-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.genreTab!=='all'){const g=all.find(g=>String(g.id)===b.dataset.genreTab);location.hash=`#genre/movie/${g.id}/${encodeURIComponent(g.name)}`}})}
async function getDetail(type,id){let d;try{d=await api(`${type}/${id}`,{append_to_response:'credits,videos'})}catch(e){const m=getItem(`${type}:${id}`);if(!m)throw e;d={...m,_offline:true}}d.media_type=type;if(!trailerList(d).length&&navigator.onLine){try{const v=await api(`${type}/${id}/videos`,{language:'en-US'});if(v.results?.length)d.videos=v}catch{}}remember([d]);return d}
function cast(p){return `<a class="cast-person" href="#person/${p.id}">${image(p.profile_path,'w185',p.name)}<strong>${esc(p.name)}</strong><small>${esc(p.character||p.known_for_department||'Actuación')}</small></a>`}
async function detail(type,id,rev,initialTab='description'){if(!['movie','tv'].includes(type)||!/^\d+$/.test(id))throw Error('Ficha no válida');const d=await getDetail(type,id);if(rev!==routeRevision)return;logVisit(d);const trailers=trailerList(d),selected=['description','cast','trailers','similar'].includes(initialTab)?initialTab:'description';setView(`<article class="detail-page"><div class="detail-layout"><div><div class="detail-visual">${image(d.backdrop_path||d.poster_path,d.backdrop_path?'w780':'w342','','detail-image')}<div class="floating-tools"><a class="circle-button" href="#home" aria-label="Volver">${icon('back')}</a><div><button class="circle-button" data-share="${keyOf(d)}" aria-label="Compartir">${icon('share')}</button><button class="circle-button" data-save="${keyOf(d)}" aria-label="Guardar">${icon('plus')}</button></div></div></div><div class="detail-heading"><h1>${esc(title(d))}</h1><div class="rating">★ ${rating(d)} <span>(${Number(d.vote_count||0).toLocaleString('es-ES')} valoraciones)</span></div><p class="detail-meta">${year(d)} · ${duration(d)}${d.genres?.length?' · '+d.genres.slice(0,3).map(g=>esc(g.name)).join(' · '):''}</p><div class="detail-actions">${trailers.length?trailerLink(d,d):'<button class="primary" disabled title="TMDB no proporciona un tráiler de YouTube para este título">'+icon('play')+'Tráiler no disponible</button>'}<button class="square-button" data-save="${keyOf(d)}" aria-label="Añadir a Mi lista">${icon('plus')}</button><button class="square-button" data-download="${keyOf(d)}" aria-label="Guardar ficha offline" title="Guardar ficha offline">${icon(downloadMap.has(keyOf(d))?'check':'download')}</button></div></div></div><section><div class="detail-tabs" role="tablist">${[['description','Descripción'],['cast','Reparto'],['trailers','Tráileres'],['similar','Similares']].map(([k,v])=>`<button role="tab" data-detail-tab="${k}" aria-selected="${k===selected}" class="${k===selected?'active':''}">${v}</button>`).join('')}</div><div id="detailContent" role="tabpanel"></div></section></div></article>`);
 let tabRevision=0;
 async function show(tab){const seq=++tabRevision;document.querySelectorAll('[data-detail-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.detailTab===tab);b.setAttribute('aria-selected',String(b.dataset.detailTab===tab))});const c=$('#detailContent');if(!c)return;
  if(tab==='description'){const site=d.homepage&&/^https?:\/\//i.test(d.homepage)?d.homepage:null;c.innerHTML=offlineNote(d._offline)+`<p class="description">${esc(d.overview||'No hay sinopsis disponible en español para este título.')}</p>${section('Reparto principal')}${d.credits?.cast?.length?`<div class="cast-rail">${d.credits.cast.slice(0,8).map(cast).join('')}</div>`:'<p class="muted tiny">El reparto no está disponible en esta ficha.</p>'}<dl class="info-grid"><div><dt>Idioma original</dt><dd>${esc(d.original_language||'No informado')}</dd></div><div><dt>Estado</dt><dd>${esc(statusName(d.status))}</dd></div>${type==='tv'?`<div><dt>Temporadas</dt><dd>${Number(d.number_of_seasons||0)}</dd></div><div><dt>Episodios</dt><dd>${Number(d.number_of_episodes||0)}</dd></div>`:''}${site?`<div><dt>Sitio oficial</dt><dd><a class="cyan" href="${esc(site)}" target="_blank" rel="noopener">Visitar ${icon('external')}</a></dd></div>`:''}</dl>`}
  else if(tab==='cast'){c.innerHTML=d.credits?.cast?.length?`<div class="grid">${d.credits.cast.map(p=>`<a class="person-card" href="#person/${p.id}"><div class="poster-box">${image(p.profile_path,'w185',p.name)}</div><strong>${esc(p.name)}</strong><small>${esc(p.character)}</small></a>`).join('')}</div>`:empty('Reparto no disponible','Consulta esta ficha con conexión.','people')}
  else if(tab==='trailers'){c.innerHTML=trailers.length?`<div class="trailer-list">${trailers.map(v=>`<a class="trailer-item" href="https://www.youtube.com/watch?v=${esc(v.key)}" target="_blank" rel="noopener">${icon('play')}<span>${esc(v.name)}<small class="muted" style="display:block">YouTube · ${esc(v.iso_639_1||'')}</small></span>${icon('external')}</a>`).join('')}</div><p class="muted tiny" style="margin-top:15px">Se abren fuera de la aplicación. Necesitan conexión.</p>`:empty('No hay tráiler disponible','TMDB no proporciona un tráiler de YouTube para este título.','play')}
  else{c.innerHTML='<div class="loading-state">Consultando títulos similares…</div>';try{const r=await api(`${type}/${id}/similar`);if(rev!==routeRevision||seq!==tabRevision)return;const items=(r.results||[]).map(m=>({...m,media_type:type}));c.innerHTML=offlineNote(r._offline)+(items.length?cards(items):empty('No hay similares disponibles','TMDB no devolvió títulos similares.','movie'))}catch(e){if(rev!==routeRevision||seq!==tabRevision)return;c.innerHTML=empty('Similares no guardados',e.message,'offline')}}
  hydrate();
 }
 document.querySelectorAll('[data-detail-tab]').forEach(b=>b.onclick=()=>show(b.dataset.detailTab));await show(selected);
}
function duration(d){const n=Number(d.runtime||d.episode_run_time?.[0]||0);return n?`${Math.floor(n/60)?Math.floor(n/60)+'h ':''}${n%60}min`:d.number_of_seasons?`${d.number_of_seasons} temporadas`:'Duración no informada'}
function statusName(s){return ({Released:'Estrenada','Post Production':'Posproducción','In Production':'En producción',Planned:'Planificada',Rumored:'Por confirmar','Returning Series':'En emisión',Ended:'Finalizada',Canceled:'Cancelada'})[s]||s||'No informado'}
async function person(id,rev){if(!/^\d+$/.test(id))throw Error('Persona no válida');const [p,c]=await Promise.all([api(`person/${id}`),api(`person/${id}/combined_credits`)]);if(rev!==routeRevision)return;const seen=new Set(),items=(c.cast||[]).filter(m=>{const k=keyOf(m);if(m.adult||seen.has(k)||!m.poster_path)return false;seen.add(k);return true}).sort((a,b)=>(b.popularity||0)-(a.popularity||0));remember(items);const born=p.birthday?new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(p.birthday+'T12:00:00Z')):'';const following=follows.some(x=>x.id===p.id);
 setView(`<article><div class="actor-visual">${image(p.profile_path,'h632',p.name,'actor-cover')}<div class="floating-tools"><a class="circle-button" href="#explore" aria-label="Volver">${icon('back')}</a><button class="circle-button" data-share-person="${p.id}" aria-label="Compartir actor">${icon('share')}</button></div></div><div class="actor-title">${image(p.profile_path,'w185',p.name,'actor-photo')}<div><h1>${esc(p.name)}</h1><p>${esc(p.known_for_department==='Acting'?'Actor / actriz':p.known_for_department||'Profesional audiovisual')}${born?'<br>Nacimiento: '+esc(born):''}${p.place_of_birth?'<br>'+esc(p.place_of_birth):''}</p></div></div><div class="actor-actions"><button class="primary" id="followActor">${following?'Siguiendo':'Seguir'}</button><a class="secondary" href="#filmography/${p.id}">Ver filmografía</a></div>${offlineNote(p._offline)}${section('Películas y series','#filmography/'+p.id)}${cards(items.slice(0,9),true)}${section('Información')}<p class="bio clamped" id="biography">${esc(p.biography||'TMDB no tiene una biografía en español para esta persona.')}</p>${p.biography?'<button class="text-button" id="expandBio">Leer más</button>':''}<p class="muted tiny">${items.length} títulos con póster en su filmografía disponible.</p></article>`);
 $('#followActor').onclick=()=>{const exists=follows.some(x=>x.id===p.id),next=exists?follows.filter(x=>x.id!==p.id):[...follows,p];if(localPut('cs_follow_v2',next)){follows=next;$('#followActor').textContent=exists?'Seguir':'Siguiendo';toast(exists?'Has dejado de seguir a esta persona':'Persona seguida en este dispositivo')}};
 if($('#expandBio'))$('#expandBio').onclick=()=>{$('#biography').classList.toggle('clamped');$('#expandBio').textContent=$('#biography').classList.contains('clamped')?'Leer más':'Leer menos'};
}
async function filmography(id,rev){const [p,c]=await Promise.all([api(`person/${id}`),api(`person/${id}/combined_credits`)]);if(rev!==routeRevision)return;const seen=new Set(),items=[...(c.cast||[]),...(c.crew||[])].filter(m=>{const k=keyOf(m);if(m.adult||seen.has(k))return false;seen.add(k);return true}).sort((a,b)=>(b.popularity||0)-(a.popularity||0));setView(`${head(p.name,'#person/'+id)}${offlineNote(c._offline)}${section('Filmografía · '+items.length+' títulos')}${items.length?cards(items):empty('Sin títulos disponibles','No hay filmografía en los datos de TMDB.','movie')}`)}
function titleRows(items,download=false){remember(items);return `<div class="title-list">${items.map(m=>{const d=seed.details[`${kind(m)}/${m.id}`]||m,pin=downloadMap.get(keyOf(m));return `<article class="title-row"><a href="#detail/${kind(m)}/${m.id}">${image(m.poster_path,'w185',title(m))}</a><div class="title-copy"><h3><a href="#detail/${kind(m)}/${m.id}">${esc(title(m))}</a></h3><span class="kind">${kind(m)==='tv'?'Serie':'Película'}</span><span class="metadata">${year(m)}${d.runtime||d.number_of_seasons?' · '+duration(d):''}</span>${download&&pin?`<span class="download-badge">${icon('check')}Ficha offline · ${(pin.bytes/1024/1024).toFixed(1)} MB</span>`:''}</div><button class="plain-icon" data-menu="${keyOf(m)}" aria-label="Opciones de ${esc(title(m))}">${icon('dots')}</button></article>`}).join('')}</div>`}
function listPage(){setView(`${head('Mi Lista')}<div class="segmented"><button data-list-tab="movie" class="${listTab==='movie'?'active':''}">Películas</button><button data-list-tab="tv" class="${listTab==='tv'?'active':''}">Series</button></div><div id="listContent"></div>`);function show(t){listTab=t;document.querySelectorAll('[data-list-tab]').forEach(b=>b.classList.toggle('active',b.dataset.listTab===t));const items=list.filter(m=>kind(m)===t).reverse();$('#listContent').innerHTML=items.length?titleRows(items):empty(t==='movie'?'Aún no hay películas':'Aún no hay series','Añade títulos con el botón +. Tu lista se guarda en este dispositivo.');hydrate()}document.querySelectorAll('[data-list-tab]').forEach(b=>b.onclick=()=>show(b.dataset.listTab));show(listTab)}
function menuRow(label,to,i='arrow',note=''){return `<a class="menu-row" href="${to}">${icon(i)}<span>${esc(label)}</span>${note?`<small>${esc(note)}</small>`:''}${icon('arrow')}</a>`}
function profilePage(){const movies=list.filter(m=>kind(m)==='movie').length,tv=list.length-movies;setView(`<div class="profile-page">${head('Perfil')}<div class="profile-head"><button class="profile-avatar" id="editProfileAvatar" aria-label="Editar perfil">${profile.avatar?`<img src="${esc(profile.avatar)}" alt="Avatar personal">`:esc(initials())}</button><div><h2>${esc(profile.name||'CarimarShow')}</h2><p>Tu universo, en este dispositivo.</p><button class="text-button" id="editProfile">Editar perfil</button></div></div><div class="profile-stats"><a href="#list"><strong>${movies}</strong><small>Películas</small></a><a href="#list"><strong>${tv}</strong><small>Series</small></a><a href="#following"><strong>${follows.length}</strong><small>Actores seguidos</small></a></div><div class="menu-list">${menuRow('Mi Lista','#list','bookmark')}${menuRow('Historial','#history','clock')}${menuRow('Descargas (offline)','#downloads','download',downloadMap.size?downloadMap.size+' fichas':'')}${menuRow('Configuración','#settings','settings')}${menuRow('Ayuda y soporte','#support','help')}<button class="menu-row danger" id="resetData">${icon('trash')}<span>Restablecer mis datos</span>${icon('arrow')}</button></div><p class="profile-note">Perfil local · Sin registro ni sesión.<br>CarimarShow ${esc(window.CARIMAR_CONFIG.version)} · Studio Lexair</p></div>`);$('#editProfile').onclick=editProfile;$('#editProfileAvatar').onclick=editProfile;$('#resetData').onclick=async()=>{if(!confirm('¿Eliminar tu lista, perfil, historial, búsquedas, personas seguidas y fichas descargadas? Esta acción no se puede deshacer.'))return;for(const k of ['cs_list_v1','cs_follow_v2','cs_history_v2','cs_recent_v2','cs_profile_v2'])localStorage.removeItem(k);for(const s of ['downloads','pinnedImages','api','images'])await dbClear(s);list=[];follows=[];history=[];recents=[];profile={name:'CarimarShow',avatar:''};downloadMap.clear();updateAvatar();profilePage();toast('Datos locales restablecidos')}}
function editProfile(){sheet(`<h2>Tu perfil local</h2><form id="profileForm"><label for="profileName">Nombre</label><input id="profileName" maxlength="40" value="${esc(profile.name||'CarimarShow')}" required><label for="profilePhoto">Avatar (opcional)</label><input id="profilePhoto" type="file" accept="image/*"><p>No se sube a un servidor. Se guarda únicamente en este dispositivo.</p><div class="sheet-actions"><button class="primary">Guardar</button><button type="button" class="secondary" id="removeAvatar">Quitar foto</button></div></form>`);let remove=false;$('#removeAvatar').onclick=()=>{remove=true;$('#profilePhoto').value='';toast('La foto se quitará al guardar')};$('#profileForm').onsubmit=async e=>{e.preventDefault();const name=$('#profileName').value.trim();if(!name)return;let avatar=remove?'':profile.avatar;const file=$('#profilePhoto').files[0];if(file){if(!file.type.startsWith('image/')||file.size>10000000)return toast('Elige una imagen de menos de 10 MB.');try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,256,256);avatar=canvas.toDataURL('image/jpeg',.8);bitmap.close()}catch{return toast('No se pudo leer la imagen. Prueba un JPG o PNG.')}}const next={name,avatar};if(localPut('cs_profile_v2',next)){profile=next;updateAvatar();closeSheet();profilePage();toast('Perfil guardado')}}}
function historyPage(){setView(`${head('Historial','#profile')}<div class="section-head"><h2>Fichas consultadas</h2><button class="text-button" id="clearHistory">Limpiar</button></div>${history.length?titleRows(history):empty('Tu historial empieza aquí','Las fichas que abras aparecerán en esta sección.','clock')}`);$('#clearHistory').onclick=()=>{if(confirm('¿Borrar el historial de fichas consultadas?')&&localPut('cs_history_v2',[])){history=[];historyPage()}}}
function followingPage(){remember(follows.map(p=>({...p,media_type:'person'})));setView(`${head('Actores seguidos','#profile')}${follows.length?cards(follows.map(p=>({...p,media_type:'person'}))):empty('Sigue a tus actores favoritos','Abre una persona y toca Seguir.','people')}`)}
function downloadsPage(){setView(`${head('Descargas offline','#profile')}<div class="notice">Se guardan fichas e imágenes, no películas ni capítulos. El catálogo incluido en el instalador permanece disponible por separado.</div>${downloadMap.size?titleRows([...downloadMap.values()].map(d=>d.item),true):empty('Todavía no has descargado fichas','Abre un título y toca el icono de descarga para guardar su ficha e imágenes.','download')}<p class="muted tiny" style="margin-top:18px">${seed.catalog.length} títulos y ${Object.keys(seed.images||{}).length} imágenes también vienen incluidos en esta versión.</p>`)}
async function downloadItem(m){if(!m)return;const k=keyOf(m);if(downloadMap.has(k))return toast('Esta ficha ya está guardada offline.');if(!navigator.onLine)return toast('Conéctate para descargar una ficha completa.');const touched=[];toast('Preparando ficha e imágenes…');try{const d=await getDetail(kind(m),String(m.id));if(d._offline)throw Error('No se pudo actualizar la ficha. Intenta descargarla con conexión.');const imageKeys=[];if(d.poster_path)imageKeys.push('w342'+d.poster_path,'w185'+d.poster_path);if(d.backdrop_path)imageKeys.push('w780'+d.backdrop_path);for(const p of (d.credits?.cast||[]).slice(0,8))if(p.profile_path)imageKeys.push('w185'+p.profile_path);let bytes=JSON.stringify(d).length,done=0;
 for(const ik of [...new Set(imageKeys)]){let blob=await dbGet('pinnedImages',ik)||await dbGet('images',ik);if(!blob){const bundled=seed.images[ik];const r=await fetch(bundled?BASE+bundled:'https://image.tmdb.org/t/p/'+ik,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('No se pudo guardar una imagen. La descarga no se ha completado.');blob=await r.blob()}if(!blob.type.startsWith('image/'))throw Error('Imagen no válida');if(!await dbPut('pinnedImages',ik,blob))throw Error('No hay espacio para completar la descarga.');touched.push(ik);bytes+=blob.size;done++;toast(`Guardando imágenes ${done}/${new Set(imageKeys).size}…`)}
 const pin={item:{...d,media_type:kind(m)},detail:d,images:[...new Set(imageKeys)],bytes,savedAt:new Date().toISOString()};if(!await dbPut('downloads',k,pin))throw Error('No hay espacio para guardar la ficha.');downloadMap.set(k,pin);document.querySelectorAll('[data-download]').forEach(b=>{if(b.dataset.download===k)b.innerHTML=icon('check')});toast('Ficha e imágenes disponibles sin conexión.');if(location.hash==='#downloads')downloadsPage();
 }catch(e){for(const ik of touched)if(![...downloadMap.values()].some(d=>d.images.includes(ik)))await dbDelete('pinnedImages',ik);toast(e.message||'No se pudo completar la descarga.')}}
async function removeDownload(k){const pin=downloadMap.get(k);if(!pin)return;await dbDelete('downloads',k);downloadMap.delete(k);for(const ik of pin.images||[]){if(![...downloadMap.values()].some(d=>d.images.includes(ik)))await dbDelete('pinnedImages',ik)}toast('Descarga eliminada. Tu lista se conserva.');if(location.hash==='#downloads')downloadsPage()}
function itemMenu(m){if(!m)return;const k=keyOf(m),saved=list.some(x=>keyOf(x)===k),pin=downloadMap.has(k);sheet(`<h2>${esc(title(m))}</h2><button class="menu-row" id="menuSave">${icon(saved?'trash':'bookmark')}<span>${saved?'Quitar de Mi lista':'Añadir a Mi lista'}</span></button><button class="menu-row" id="menuDownload">${icon(pin?'trash':'download')}<span>${pin?'Eliminar descarga offline':'Guardar ficha offline'}</span></button><button class="menu-row" id="menuShare">${icon('share')}<span>Compartir ficha</span></button>`);$('#menuSave').onclick=()=>{saveItem(m);closeSheet();if(location.hash==='#list')listPage()};$('#menuDownload').onclick=()=>{closeSheet();pin?removeDownload(k):downloadItem(m)};$('#menuShare').onclick=()=>{closeSheet();share(m)}}
function sheet(html){$('#sheetContent').innerHTML=html;$('#sheet').showModal();hydrate()}
function closeSheet(){$('#sheet').close()}
$('#sheet').addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeSheet()});
async function share(m,personId){const url=`https://carimarshow-native.vercel.app/app/#${personId?'person/'+personId:'detail/'+kind(m)+'/'+m.id}`,t=personId?'Persona en CarimarShow':title(m);try{if(navigator.share){await navigator.share({title:t,url});return}if(navigator.clipboard){await navigator.clipboard.writeText(url);toast('Enlace copiado');return}}catch(e){if(e.name==='AbortError')return}sheet(`<h2>Compartir</h2><p>Copia este enlace para compartir la ficha:</p><input readonly id="shareUrl" value="${esc(url)}"><button class="primary" id="copyLink">Copiar enlace</button>`);$('#copyLink').onclick=()=>{$('#shareUrl').select();if(document.execCommand('copy')){toast('Enlace copiado');closeSheet()}else toast('Mantén pulsado el enlace para copiarlo.')};}
async function settings(){const movies=list.filter(m=>kind(m)==='movie').length,tv=list.length-movies;setView(`${head('Configuración','#profile')}<div class="settings-grid"><section class="panel"><h2>Lo que sigues</h2><p>${movies} películas · ${tv} series · ${follows.length} personas</p><div class="stats-graph" role="img" aria-label="${movies} películas y ${tv} series"><span style="width:${list.length?movies/list.length*100:0}%"></span></div><div class="legend"><span>Películas</span><span>Series</span></div><a class="secondary small" href="#following" style="margin-top:18px">Ver personas seguidas</a></section><section class="panel"><h2>Almacenamiento</h2><p>Las fichas consultadas y sus imágenes se guardan automáticamente. Las descargas explícitas se conservan por separado.</p><p id="storageInfo" class="storage-stat">Calculando…</p><button class="secondary small" id="clearCache">Borrar caché automática</button><p class="tiny">No borra tu lista, perfil, descargas ni el catálogo incluido.</p><a class="cyan tiny" href="#downloads">Gestionar fichas offline →</a></section><section class="panel"><h2>CarimarShow-shop</h2><dl><dt>Dirección</dt><dd>Lealtad 559 e/ Salud y Dragones, Centro Habana</dd><dt>Horario</dt><dd>L–V · 1:00 PM–10:00 PM</dd><dt>Teléfonos</dt><dd><a href="tel:+5353324928">+53 53324928</a><br><a href="tel:+5378660658">+53 78660658</a></dd><dt>Correo</dt><dd><a href="mailto:carimarshowapk@qmail.com">carimarshowapk@qmail.com</a></dd></dl><a class="primary small" href="https://wa.me/5353324928" target="_blank" rel="noopener">Contactar por WhatsApp</a></section><section class="panel"><h2>Sobre la aplicación</h2><p>Desarrollado por <strong>Studio Lexair · Yolexis</strong></p><dl><dt>Versión</dt><dd>${esc(window.CARIMAR_CONFIG.version)}</dd><dt>Catálogo local</dt><dd>${seed.catalog.length} títulos</dd><dt>Fecha</dt><dd>${esc(seed.generatedAt?.slice(0,10)||'—')}</dd></dl><div class="sheet-actions"><button class="primary small" id="installApp">Instalar web</button><a class="secondary small" href="https://github.com/StudioLexair/CarimarShow-Native/releases/latest" target="_blank" rel="noopener">APK / Windows</a></div><p><a class="cyan" href="#privacy">Privacidad y datos locales →</a></p></section></div>${legal()}`);$('#clearCache').onclick=async()=>{if(!confirm('¿Borrar consultas e imágenes de la caché automática? Tus descargas y Mi lista se conservan.'))return;await dbClear('api');await dbClear('images');toast('Caché automática borrada');storageInfo()};$('#installApp').onclick=install;storageInfo()}
async function storageInfo(){try{const d=await navigator.storage?.estimate();if($('#storageInfo'))$('#storageInfo').textContent=d?`${((d.usage||0)/1024/1024).toFixed(1)} MB de datos locales en este origen.`:'Datos guardados localmente.'}catch{if($('#storageInfo'))$('#storageInfo').textContent='Este navegador no informa del espacio usado.'}}
function support(){setView(`${head('Ayuda y soporte','#profile')}<section class="panel"><h2>Estamos para ayudarte</h2><p>Para consultas sobre el catálogo y pedidos, contacta directamente con CarimarShow-shop.</p><a class="primary" href="https://wa.me/5353324928" target="_blank" rel="noopener">WhatsApp</a>${menuRow('Llamar al negocio','tel:+5353324928','phone')}${menuRow('Enviar correo','mailto:carimarshowapk@qmail.com','mail')}</section><section class="panel"><h2>¿Cómo funciona sin conexión?</h2><p>La app incluye un catálogo inicial. También conserva consultas y permite guardar fichas explícitamente. Para actualizar datos, buscar títulos nuevos o abrir YouTube necesitas internet.</p><h2>¿Dónde están las películas?</h2><p>CarimarShow muestra información de TMDB. No sirve archivos de películas o capítulos. «Ver tráiler» abre YouTube fuera de la app.</p><h2>¿Por qué no hay una cuenta?</h2><p>El perfil, lista y preferencias son locales. No hay registro, contraseña ni sincronización entre dispositivos.</p></section>`)}
function privacy(){setView(`${head('Privacidad','#settings')}<section class="panel"><h2>Tu información, en tu dispositivo</h2><p>Tu perfil, avatar, lista, búsquedas recientes, historial, personas seguidas y fichas offline se guardan localmente. No se suben a un servidor y no se sincronizan entre dispositivos.</p><p>Las consultas online pasan por el servidor de CarimarShow en Vercel y la API de TMDB. Los pósteres se obtienen de TMDB. Esos proveedores pueden registrar datos técnicos como la IP y la consulta, según sus políticas.</p><p>YouTube, WhatsApp y los sitios externos tienen sus propias políticas. No solicitamos ubicación, micrófono, contactos ni cámara. La foto de perfil se selecciona voluntariamente desde tus archivos.</p><p>La caché automática conserva hasta 250 consultas y 100 imágenes. Las descargas seleccionadas se guardan por separado hasta que las elimines o el sistema borre los datos. Desinstalar, borrar datos o limpiar el navegador puede eliminar la lista y el perfil.</p><p>Puedes borrar la caché, eliminar descargas o restablecer todos tus datos desde Perfil. Contacto: <a class="cyan" href="mailto:carimarshowapk@qmail.com">carimarshowapk@qmail.com</a>.</p></section>`)}
async function install(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return}sheet(`<h2>Lleva CarimarShow contigo</h2><p>${/iPhone|iPad|iPod/.test(navigator.userAgent)?'En Safari: Compartir → Añadir a la pantalla de inicio.':'En Chrome o Edge, abre el menú del navegador y busca «Instalar aplicación». En Android y Windows también puedes usar nuestros instaladores.'}</p><a class="primary" href="https://github.com/StudioLexair/CarimarShow-Native/releases/latest" target="_blank" rel="noopener">Descargar instaladores</a>`)}
async function route(){const rev=++routeRevision;searchRevision++;const p=(location.hash.slice(1)||'home').split('/'),name=p[0];const top=['home'].includes(name);$('#appHeader').classList.toggle('subpage',!top);const nav=['browse','genres','genre','person','filmography','search','explore'].includes(name)?'explore':['settings','support','privacy','history','downloads','following','profile'].includes(name)?'profile':name==='detail'?'home':name;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});closeSheet();window.scrollTo({top:0,behavior:'instant'});
 const sync=['list','profile','settings','history','following','downloads','support','privacy'];if(!sync.includes(name))setView('<div class="loading-state">Cargando información…</div>');
 try{if(name==='home')await home(rev);else if(name==='explore'||name==='search')await explore(rev,p[1]?decodeURIComponent(p[1]):'');else if(name==='browse')await browse(p[1],rev);else if(name==='genres')await genresPage(rev);else if(name==='genre'){if(!['movie','tv'].includes(p[1])||!/^\d+$/.test(p[2]))throw Error('Categoría inválida');await browse(p[1],rev,1,p[2],decodeURIComponent(p[3]||''))}else if(name==='detail')await detail(p[1],p[2],rev,p[3]);else if(name==='person')await person(p[1],rev);else if(name==='filmography')await filmography(p[1],rev);else if(name==='list')listPage();else if(name==='profile')profilePage();else if(name==='history')historyPage();else if(name==='following')followingPage();else if(name==='downloads')downloadsPage();else if(name==='settings')await settings();else if(name==='support')support();else if(name==='privacy')privacy();else location.hash='#home'}catch(e){if(rev===routeRevision)setView(`${head('Volver al inicio','#home')}${empty('Información no disponible',e.message,'offline')}<div class="more-wrap"><button class="primary" data-retry>Intentar de nuevo</button></div>`)}
}
view.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){saveItem(getItem(save.dataset.save));return}const menu=e.target.closest('[data-menu]');if(menu){itemMenu(getItem(menu.dataset.menu));return}const dl=e.target.closest('[data-download]');if(dl){downloadItem(getItem(dl.dataset.download));return}const sh=e.target.closest('[data-share]');if(sh){share(getItem(sh.dataset.share));return}const sp=e.target.closest('[data-share-person]');if(sp){share(null,sp.dataset.sharePerson);return}if(e.target.closest('[data-retry]'))route()});
function connection(){const on=navigator.onLine;$('#connection').classList.toggle('offline',!on);$('#connection').title=on?'Con conexión de red':'Sin conexión de red';$('#connection').setAttribute('aria-label',on?'Con conexión':'Sin conexión')}
function progress(n,msg){$('#splashProgress').value=n;$('#splashMessage').textContent=msg}
window.addEventListener('hashchange',route);window.addEventListener('online',()=>{connection();toast('Conexión recuperada. Abre una sección para actualizarla.')});window.addEventListener('offline',connection);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('appinstalled',()=>{installPrompt=null;toast('CarimarShow instalada')});window.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)){e.preventDefault();location.hash='#explore'}});
(async()=>{icons();connection();updateAvatar();try{if(sessionStorage.getItem('cs_boot_v2'))$('#splash').hidden=true}catch{}progress(15,'Abriendo el catálogo incluido…');try{const r=await fetch(BASE+'catalog-snapshot.json');if(r.ok)seed=await r.json()}catch{}progress(45,'Recuperando tus datos locales…');await dbPromise;for(const d of await dbAll('downloads'))if(d?.item)downloadMap.set(keyOf(d.item),d);remember([...seed.catalog,...list,...history]);progress(65,'Consultando tus próximas historias…');await route();progress(100,'Todo listo.');$('#splash').hidden=true;try{sessionStorage.setItem('cs_boot_v2','1')}catch{}
 if('serviceWorker'in navigator&&!window.CARIMAR_CONFIG.apiOrigin){try{for(const r of await navigator.serviceWorker.getRegistrations())if(new URL(r.scope).pathname==='/')await r.unregister();await navigator.serviceWorker.register(BASE+'sw.js',{scope:BASE})}catch{}}
})();
